public final class FileCache {
    private final Lock strategy;             // ReentrantLock, or readLock()/writeLock()
    public FileCache(Lock strategy) { this.strategy = strategy; }
    public String find(String path) {
        strategy.lock();
        try {
            return find_i(path);             // _i assumes the lock is held
        } finally {
            strategy.unlock();               // Scoped Locking emulated
        }
    }
}

